#!/bin/bash
# ============================================================
# Telegram Guard block-card visual patch v2 — auto-apply script
#
# File touched (1):
#
#   - .../shield/core/ShieldBlockCard.java
#       a) Background scrim + glow (unchanged from the previous version of
#          this patch): a translucent dark layer with a soft radial glow in
#          the card's accent colors, instead of a fully transparent
#          background. Works on every Android version this app supports.
#       b) Escalation countdown ring — FIXED to not assume a fixed duration.
#          The real escalation duration (5 min, then 30 min, etc.) is
#          controlled elsewhere and varies, so instead of a hardcoded
#          ceiling, the ring now treats whatever time is left the MOMENT
#          THE CARD OPENS as its own 100%, then live-ticks down to 0 over
#          that block's actual remaining duration — correct no matter how
#          long the real escalation window is. The big "Xh Ym" label updates
#          every second along with the ring.
#       c) No text/copy was changed.
#
# Run this from your project ROOT folder:
#   bash apply_blockcard_patch.sh
# ============================================================

set -e

if [ ! -d "android/app/src/main/java/com/mylifeos/app/shield" ]; then
  echo "ERROR: run this script from the project ROOT folder (android/ not found here)."
  exit 1
fi

STAMP=$(date +%Y%m%d_%H%M%S)
BACKUP_DIR="blockcard_patch_backup_$STAMP"
mkdir -p "$BACKUP_DIR"

backup_and_write() {
  local target="$1"
  local content_file="$2"
  mkdir -p "$(dirname "$target")"
  if [ -f "$target" ]; then
    mkdir -p "$BACKUP_DIR/$(dirname "$target")"
    cp "$target" "$BACKUP_DIR/$target"
  fi
  cp "$content_file" "$target"
  echo "  updated: $target"
}

WORKDIR=$(mktemp -d)
trap 'rm -rf "$WORKDIR"' EXIT

echo "Backing up + applying patch..."
echo "Backups going to: $BACKUP_DIR/"
echo ""
FILE_1_B64=""
echo "${FILE_1_B64}" | base64 -d > "$WORKDIR/decoded_1"
backup_and_write "android/app/src/main/java/com/mylifeos/app/shield/core/ShieldBlockCard.java" "$WORKDIR/decoded_1"

echo ""
echo "Done. 1 file updated, backup saved in $BACKUP_DIR/"
echo ""
echo "Next step: rebuild the APK as usual."
